111:   // a list input is a dynamic group of inputs, like jobs
112:   const [listInputs, setListInputs] = useState({
113:     jobs: [emptyListInputItem("jobs")],
114:     educations: [emptyListInputItem("educations")],
115:     languages: [emptyListInputItem("languages")],
116:   });
117:   const [errors, setErrors] = useState({
118:     jobs: [], // {index, field}
119:     educations: [],
120:     languages: [],
121:   });
122:   const { jobs, educations, languages } = listInputs;
123:   // handle form simple input changes
124:   const handleInputChange = (name, value) => {
125:     setFormData((formData) => ({ ...formData, [name]: value }));
126:   };
127:   // handle list input changes
128:   const handleListInputChange = (listInputName, index, inputName, value) => {
129:     setListInputs((listInputs) => {
130:       let listInput = listInputs[listInputName];
131:       let newListInput = listInput.map((item, i) => {
132:         if (i !== index) return item;
133:         else return { ...item, [inputName]: value };
134:       });
135:       return { ...listInputs, [listInputName]: newListInput };
136:     });
137:   };
