139:   const validateDate = (listInputName, index, startDate, endDate) => {
140:     setErrors((errs) => {
141:       const err = [...errs[listInputName]];
142:       const isInValid =
143:         endDate && startDate && moment(endDate).isSameOrBefore(startDate);
144:       const item = err.find((x) => x.index === index && x.field);
145:       if (!isInValid) {
146:         _.remove(err, {
147:           index: index,
148:           field: "startDate",
149:         });
150:       } else {
151:         if (!item) {
152:           err.push({
153:             index: index,
154:             field: "startDate",
155:           });
156:         }
157:       }
158: 
159:       return { ...errs, [listInputName]: err };
160:     });
161:   };
162: 
163:   const hasError = (listInputName, index, inputName) => {
164:     return (
165:       errors &&
166:       errors[listInputName].length > 0 &&
167:       errors[listInputName].some(
168:         (x) => x.index === index && x.field === inputName
169:       )
170:     );
171:   };
