281:         if (languagesExpValue) {
282:           // languagesExpValue is array of languages. fill it to state
283:           setListInputs((listInputs) => ({
284:             ...listInputs,
285:             languages: languagesExpValue.map((l) => ({
286:               language: l.language,
287:               spokenLevel: l.spokenLevel,
288:               writtenLevel: l.writtenLevel,
289:             })),
290:           }));
291:         }
292:       })
293:       .catch((e) => {
294:         setIsLoading(false);
295:         // eslint-disable-next-line no-console
296:         console.log(e);
297:       });
298:     scrollToTop();
299:   }, []);
